import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/update-prefs.png",p=JSON.parse('{"title":"Updates","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/update.md","filePath":"en/features/update.md"}'),s={name:"en/features/update.md"};function r(l,e,h,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h1><p>Automatic checks for new versions, Check for updates, downloading and installing a new version from inside Relio, and updating the portable version. Available from 1.0.0.</p><p>How to turn on notices the first time you run Relio is in <a href="/relio/en/quick/start">Install and open your first file</a> in Quick start.</p><h2 id="turning-automatic-checks-on-and-off" tabindex="-1">Turning automatic checks on and off <a class="header-anchor" href="#turning-automatic-checks-on-and-off" aria-label="Permalink to &quot;Turning automatic checks on and off&quot;">​</a></h2><ul><li>The first time you run Relio, a bar at the bottom of the window says &quot;Want to know when a new version is out? Relio checks the public releases page once a day for version information only.&quot; <strong>Yes, let me know</strong> turns checks on and <strong>No thanks</strong> turns them off. If you close the bar without answering, the setting stays undecided (treated as off).</li><li>To change it later, turn <strong>Check for new versions automatically (once a day)</strong> on or off in Tools › Settings › General. Turning it on checks once right away.</li><li>When on, Relio checks in the background shortly after starting, and only if a day has passed since the last check. If a check fails, it is not retried; Relio checks again the next day.</li><li>The result of the last check is shown below the setting (&quot;Last checked: … — Up to date&quot; / &quot;… — New version …&quot; / &quot;… — Couldn&#39;t check&quot;).</li></ul><figure class="shot" data-scene="update-prefs"><img src="'+i+'" alt="The Updates field in Settings › General — the automatic check checkbox and its description" loading="lazy"><figcaption>The Updates field in Settings › General — the automatic check checkbox and its description</figcaption></figure><h2 id="what-is-sent-and-received" tabindex="-1">What is sent and received <a class="header-anchor" href="#what-is-sent-and-received" aria-label="Permalink to &quot;What is sent and received&quot;">​</a></h2><p>A check only downloads a version information file from a fixed address on the public releases page. Relio does not send its version, information about your PC or anything else. GitHub can, however, see the IP address that connects. Check results are kept only in this PC&#39;s app settings.</p><h2 id="checking-manually" tabindex="-1">Checking manually <a class="header-anchor" href="#checking-manually" aria-label="Permalink to &quot;Checking manually&quot;">​</a></h2><p>Help › <strong>Check for updates…</strong> checks right away, regardless of the automatic check setting. The <strong>Check for updates</strong> buttons in the About Relio and What&#39;s new windows do the same. The result appears in a small window.</p><ul><li>If you are up to date: &quot;You&#39;re on the latest version (…).&quot;</li><li>If a new version is available: the notice described below.</li><li>If the check fails: the reason and an <strong>Open releases page</strong> link (see &quot;When the check fails&quot; below).</li></ul><h2 id="new-version-notice" tabindex="-1">New version notice <a class="header-anchor" href="#new-version-notice" aria-label="Permalink to &quot;New version notice&quot;">​</a></h2><p>When the automatic check finds a new version, a &quot;Relio … is available&quot; notice appears at the bottom right of the window. Click <strong>Details</strong> to open the notice window.</p><ul><li>The title &quot;A new version is available&quot;, <code>Current … → New …</code>, the release date, a summary of changes and a <strong>Show full change history</strong> link.</li><li><strong>Install now</strong> — Downloads and installs it (see below).</li><li><strong>Later</strong> — Closes the window. You are reminded at the next automatic check.</li><li><strong>Skip this version</strong> — You are not reminded about this version again; you will be when a newer one comes out. When you check manually, a skipped version is still shown, with &quot;You chose to skip this version&quot;.</li></ul><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><ol><li>Click <strong>Install now</strong> and a progress bar (&quot;Downloading… received / total&quot;) appears in the same window. You can <strong>Cancel</strong>, and you can keep working in the meantime.</li><li>The signature of the downloaded file is checked. If it does not match, nothing is installed.</li><li>If there are unsaved documents, Relio says &quot;Unsaved documents: n. Relio must close to install.&quot; and asks <strong>Save all and install</strong> · <strong>Install without saving</strong> · <strong>Cancel</strong>.</li><li>After &quot;Starting the installer. Relio will reopen when it&#39;s done.&quot;, Relio closes, the installer runs, and Relio opens again.</li></ol><p>If a task such as an export is in progress, you can install after it finishes. Your settings, connection list and backups are kept.</p><h2 id="portable-version" tabindex="-1">Portable version <a class="header-anchor" href="#portable-version" aria-label="Permalink to &quot;Portable version&quot;">​</a></h2><p>The portable version (unzipped from <code>Relio_&lt;version&gt;_x64_portable.zip</code>) checks and notifies you the same way. It does not install itself, though: the notice window says &quot;The portable version can&#39;t update itself. Download the new zip and replace it.&quot; with an <strong>Open download page</strong> button. Download the new zip, unzip it and use its <code>relio.exe</code>. It uses the same settings folder as the installed version, so your settings carry over.</p><h2 id="when-the-check-fails" tabindex="-1">When the check fails <a class="header-anchor" href="#when-the-check-fails" aria-label="Permalink to &quot;When the check fails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What to do</th></tr></thead><tbody><tr><td>Couldn&#39;t reach the update server. Check your internet connection or company network settings.</td><td>Check your internet connection or proxy, or download from the releases page yourself.</td></tr><tr><td>Couldn&#39;t read the update information. Try again later or download it from the releases page.</td><td>Check again a little later.</td></tr><tr><td>The downloaded file&#39;s signature didn&#39;t match, so it wasn&#39;t installed. …</td><td>The file may be damaged or altered. Download it from the releases page yourself.</td></tr><tr><td>Couldn&#39;t download the new version (…).</td><td>Click <strong>Try again</strong> or check your disk space.</td></tr><tr><td>Installation failed. Relio is unchanged. …</td><td>Download the installer from the releases page and install it yourself.</td></tr></tbody></table><p>If an automatic check fails, nothing is shown on screen; Relio checks again the next day.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>On company networks that use a proxy, Relio follows the Windows user proxy settings (or environment variables such as <code>HTTPS_PROXY</code>). On networks that set the proxy only through an automatic configuration script (PAC), the check may not work; in that case, download from the releases page yourself.</p></div><h2 id="installing-manually" tabindex="-1">Installing manually <a class="header-anchor" href="#installing-manually" aria-label="Permalink to &quot;Installing manually&quot;">​</a></h2><p>At any time, you can download the new installer <code>Relio_&lt;version&gt;_x64-setup.exe</code> from <a href="https://github.com/relio-hq/relio/releases/latest" target="_blank" rel="noreferrer">Releases</a> and run it; it installs over the old version and keeps your settings. Moving from a beta version to 1.0.0 requires one manual installation.</p>',25)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
